<?php
declare(strict_types=1); namespace App\Http\Controllers\Personnel;
use App\Http\Controllers\Controller;use App\Http\Requests\Personnel\UpdatePersonnelAccountRequest;use App\Models\{Personnel,User};use App\Services\Personnel\PersonnelService;use Illuminate\Http\{RedirectResponse,Request};use Illuminate\View\View;
class PersonnelAccountController extends Controller {public function __construct(private PersonnelService $service){}public function edit(Personnel $personnel):View{return view('personnel.account',['title'=>'Hubungkan Akun','personnel'=>$personnel->load('user'),'accounts'=>User::whereDoesntHave('personnel')->orderBy('name')->get()]);}public function update(UpdatePersonnelAccountRequest $r,Personnel $personnel):RedirectResponse{$this->service->connect($personnel,(int)$r->validated('user_id'),$r->user());return redirect()->route('personnel.show',$personnel)->with('status','Akun berhasil dihubungkan dengan personalia.');}public function destroy(Request $r,Personnel $personnel):RedirectResponse{$this->service->disconnect($personnel,$r->user());return back()->with('status','Hubungan akun berhasil dilepaskan.');}}
